function get(card){
 const result=[...(EXAMPLES[card.id]||[])];
 if(!result.length){
  const own=card.example&&!/^Vocabulario B2 del PDF/i.test(card.example)?card.example:'';
  if(own)result.push({en:own,es:card.exampleEs||NATIVE_TRANSLATIONS[card.id]||''});
  for(const e of byWord.get(normal(card.en))||[])if(!result.some(x=>x.en===e.en))result.push(e);
 }
 return result;
}
